/* @lc app=leetcode id=3942 lang=kotlin */ class Solution { fun minOperations(nums: IntArray): Int = nums.size.let { n -> (if ((0 until n).all { nums[it] == (nums[0] + it) % n }) 0 to nums[0] else if ((0 until n).all { nums[it] == Math.floorMod(nums[0] - it, n) }) 1 to nums[0] else null).let { st -> if (st == null) -1 else IntArray(2 * n) { -1 }.also { d -> d[st.first * n + st.second] = 0 }.let { d -> generateSequence(listOf(st.first * n + st.second) to 0) { (f, lv) -> f.flatMap { u -> (u / n).let { t -> (u % n).let { s -> listOf(if (t == 0) (s + 1) % n else n + (s - 1 + n) % n, if (t == 0) n + (s - 1 + n) % n else (s + 1) % n) } } }.filter { d[it] == -1 }.distinct().onEach { d[it] = lv + 1 }.takeIf { it.isNotEmpty() }?.let { it to lv + 1 } }.count().let { d[0] } } } } }